// Copies native/ChatDockWindow.swift into a TypeScript module, so the host
// bundle carries the window's source to any machine that builds it.
// Run after editing the Swift file: node scripts/embed-native.mjs
import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const source = readFileSync(new URL("native/ChatDockWindow.swift", root), "utf8");
const out =
  "// Generated by scripts/embed-native.mjs from native/ChatDockWindow.swift. Do not edit.\n" +
  "export const WINDOW_SOURCE = " + JSON.stringify(source) + ";\n";
writeFileSync(new URL("src/adapters/bb/window-source.generated.ts", root), out);
